WITH metrics AS (SELECT id, customer_id, device, browser, started_at, country, ROW_NUMBER() OVER w_running AS row_seq, ROW_NUMBER() OVER w_running AS row_seq_2, ROW_NUMBER() OVER w_ordered AS seq_no FROM sessions WINDOW w_running AS (PARTITION BY country ORDER BY started_at DESC, id), w_ordered AS (PARTITION BY browser ORDER BY started_at DESC, id)) SELECT id, customer_id, device, started_at, row_seq, row_seq_2, seq_no FROM metrics;
